/**
 * OSM layers generated by `npm run fetch-osm` (see scripts/fetch-osm.ts).
 * Don't edit the JSON by hand; re-run the script instead (it also writes
 * campus.topo.json, the compact file the app actually loads).
 * Data © OpenStreetMap contributors, ODbL.
 */
import type { Feature, FeatureCollection, LineString, MultiPolygon, Polygon } from 'geojson'
import { feature } from 'topojson-client'
import type { Topology } from 'topojson-specification'
import topoJson from './osm/campus.topo.json'
import metaJson from './osm/meta.json'

// One compact TopoJSON (written by scripts/derive-osm.ts) decoded back into
// the per-layer GeoJSON the scene works with.
const topo = topoJson as unknown as Topology
const layer = (name: string) => feature(topo, topo.objects[name]) as unknown

export interface OsmBaseProps {
  id: string
  /** True when the feature lies inside the campus boundary. */
  inside: boolean
  name?: string
  'name:en'?: string
}

export interface BuildingProps extends OsmBaseProps {
  building: string
  'building:levels'?: string
  height?: string
  min_height?: string
}

export interface RoadProps extends OsmBaseProps {
  class: 'main' | 'minor' | 'path'
  highway: string
  service?: string
  bridge?: string
}

export interface AreaProps extends OsmBaseProps {
  landuse?: string
  leisure?: string
  natural?: string
  waterway?: string
  sport?: string
}

type FC<G extends Polygon | MultiPolygon | LineString, P> = FeatureCollection<G, P>

export const campusBoundary = layer('boundary') as Feature<Polygon | MultiPolygon>
export const buildings = layer('buildings') as FC<Polygon | MultiPolygon, BuildingProps>
export const roads = layer('roads') as FC<LineString, RoadProps>
export const water = layer('water') as FeatureCollection<Polygon | MultiPolygon | LineString, AreaProps>
export const green = layer('green') as FC<Polygon | MultiPolygon, AreaProps>
export const sport = layer('sport') as FC<Polygon | MultiPolygon, AreaProps>
export const osmMeta = metaJson
